WITH bal AS (SELECT a.object_id AS id, json_extract_string(a.state,'$.type') AS typ, SUM(CASE WHEN json_extract_string(p.state,'$.side') = 'debit' THEN CAST(json_extract(p.state,'$.amount') AS BIGINT) ELSE -CAST(json_extract(p.state,'$.amount') AS BIGINT) END) AS b FROM objects p JOIN objects a ON json_extract_string(p.state,'$.account') = a.object_id WHERE p.object_type = 'posting' AND a.object_type = 'account' AND COALESCE(json_extract_string(p.state,'$.book'), 'main') = 'pl-stat' GROUP BY 1, 2) SELECT op, line, amount, o AS _of FROM (SELECT 1 AS k, '' AS op, 'Przychody' AS line, -COALESCE(SUM(b), 0) AS amount, string_agg(id, ',' ORDER BY id) AS o FROM bal WHERE typ = 'revenue' UNION ALL SELECT 2, '-', 'Koszty', COALESCE(SUM(b), 0), string_agg(id, ',' ORDER BY id) FROM bal WHERE typ = 'expense' UNION ALL SELECT 3, '=', 'Wynik przed opodatkowaniem', -COALESCE(SUM(b), 0), string_agg(id, ',' ORDER BY id) FROM bal WHERE typ IN ('revenue', 'expense')) ORDER BY k
